import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide } = ctx.THREE;

  const root = new Group();
  const content = new Group();
  root.add(content);
  root.userData.handlers = {};
  const cleanups = [];

  const colors = config.intent?.visualSpec?.colors ?? {};
  const cInk = new Color(colors.ink ?? '#16161d');
  const cPaper = new Color(colors.paper ?? '#e8ecf2');
  const cAccent = new Color(colors.accent ?? '#ff2a38');
  const cSurface = new Color(colors.surface ?? '#0b0b10');

  const surfV = vec3(cSurface.r, cSurface.g, cSurface.b);
  const inkV = vec3(cInk.r, cInk.g, cInk.b);
  const accentV = vec3(cAccent.r, cAccent.g, cAccent.b);

  // Engineered gradient plate behind the tagline (no flat void)
  const plateMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const yy = uv().y;
  const grad = mix(surfV, inkV, smoothstep(0.0, 1.0, yy));
  const edge = smoothstep(0.05, 0.0, yy);
  plateMat.colorNode = mix(grad, accentV, edge.mul(0.5));
  plateMat.side = DoubleSide;
  const plate = new Mesh(new PlaneGeometry(2.9, 0.72), plateMat);
  plate.position.z = -0.2;
  content.add(plate);
  cleanups.push(() => { plateMat.dispose(); plate.geometry.dispose(); });

  // Isolated hero asset as a small machined emblem to the left of the wordmark
  const imgMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const img = new Mesh(new PlaneGeometry(0.5, 0.3125), imgMat); // 1.6:1 (512x320)
  img.position.set(-1.0, 0.0, 0.0);
  content.add(img);
  cleanups.push(() => { imgMat.dispose(); img.geometry.dispose(); });
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      imgMat.map = tex;
      imgMat.needsUpdate = true;
    });
  }

  // Text via MSDF atlas (ASCII only)
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const raw = items.map((i) => i.text).join(' ').trim();
  const safe = raw
    .replace(/[\u2014\u2013]/g, '-')
    .replace(/\u00B7/g, '-')
    .replace(/[^\x20-\x7E]/g, '')
    .replace(/\s{2,}/g, ' ')
    .trim();
  const fontSize = items[0]?.typography?.fontSize ?? 42;
  const text = ctx.fontAtlas.createText(safe || 'Atelier Noir', {
    fontSize: fontSize,
    color: '#e8ecf2',
    align: 'center',
  });
  text.position.set(0.35, 0.0, 0.06);
  content.add(text);

  // Accent underline (signal red, <=10% of frame)
  const lineMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  lineMat.colorNode = accentV.mul(0.85);
  const line = new Mesh(new PlaneGeometry(0.22, 0.014), lineMat);
  line.position.set(-0.85, -0.025, 0.02);
  content.add(line);
  cleanups.push(() => { lineMat.dispose(); line.geometry.dispose(); });

  // Entrance: rise-in + weighted settle, fade plate/emblem
  content.position.y = 0.4;
  const tl = gsap.timeline({ delay: 0.2 });
  tl.to(content.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  tl.from(content.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.9, ease: 'power4.out' }, 0);
  tl.fromTo(plateMat, { opacity: 0.0 }, { opacity: 0.92, duration: 0.6, ease: 'power2.out' }, 0);
  tl.fromTo(imgMat, { opacity: 0.0 }, { opacity: 1.0, duration: 0.6, ease: 'power2.out' }, 0.05);

  root.userData.cleanup = () => {
    tl.kill();
    cleanups.forEach((fn) => fn());
  };

  return root;
}
